import React, { useState, useEffect } from "react";
import { Link } from "react-router-dom";
import { fetchBooks } from "../api";
import { Book } from "../types";

const BookList: React.FC = () => {
  const [books, setBooks] = useState<Book[]>([]);
  const [query, setQuery] = useState<string>("");
  const [page, setPage] = useState<number>(1);
  const [totalPages, setTotalPages] = useState<number>(1);

  // 책 목록을 불러오는 함수
  useEffect(() => {
    const fetchData = async () => {
      const { books, totalPages } = await fetchBooks(query, page);
      setBooks(books);
      setTotalPages(totalPages);
    };
    fetchData();
  }, [query, page]); // 검색어(query)나 페이지(page)가 변경될 때마다 호출

  const handleSearchChange = (event: React.ChangeEvent<HTMLInputElement>) => {
    setQuery(event.target.value);  // 검색어 상태 업데이트
    setPage(1);  // 검색어가 변경되면 첫 페이지로 리셋
  };

  const handlePageChange = (newPage: number) => {
    setPage(newPage);
  };

  return (
    <div className="max-w-4xl mx-auto px-4 py-8">
      <h1 className="text-3xl font-bold mb-6 text-center text-gray-800">📚 서점 도서 목록</h1>

      <div className="mb-6">
        <input
          type="text"
          className="w-full px-4 py-2 border border-gray-300 rounded-lg shadow-sm focus:ring-2 focus:ring-blue-400 focus:outline-none"
          placeholder="제목 또는 저자 검색"
          value={query}
          onChange={handleSearchChange}
        />
      </div>

      <ul className="space-y-4">
        {books.map((book) => (
          <li key={book._id} className="border border-gray-200 rounded-lg p-4 shadow-sm hover:shadow-md transition-shadow">
            <Link to={`/books/${book._id}`} className="block hover:text-blue-600">
              <h2 className="text-xl font-semibold">{book.title}</h2>
              <p className="text-gray-600">{book.author}</p>
            </Link>
          </li>
        ))}
      </ul>

      <div className="flex justify-between items-center mt-8">
        <button
          onClick={() => handlePageChange(page - 1)}
          disabled={page === 1}
          className={`px-4 py-2 rounded-md text-white ${
            page === 1 ? "bg-gray-300 cursor-not-allowed" : "bg-blue-500 hover:bg-blue-600"
          }`}
        >
          이전
        </button>
        <span className="text-gray-700">
          페이지 <strong>{page}</strong> / {totalPages}
        </span>
        <button
          onClick={() => handlePageChange(page + 1)}
          disabled={page === totalPages}
          className={`px-4 py-2 rounded-md text-white ${
            page === totalPages ? "bg-gray-300 cursor-not-allowed" : "bg-blue-500 hover:bg-blue-600"
          }`}
        >
          다음
        </button>
      </div>
    </div>
  );
};

export default BookList;
